//! File and folder icons from VS Code's Material Icon Theme (MIT licensed),
//! matched the way the theme does in VS Code: exact file names first, then
//! the longest matching extension (`users.controller.ts` before `.ts`), then
//! the default icon. Folders match by name and have open and closed variants.
//!
//! The icons live in `app/assets/bundled/svg/material/` and the manifest next
//! to this file; both are generated by `script/update_material_icons.py`.

use std::collections::HashMap;
use std::sync::OnceLock;

use serde::Deserialize;

const MANIFEST: &str = include_str!("material_icons/manifest.json");

#[derive(Debug, Default, Deserialize)]
#[serde(rename_all = "camelCase")]
struct Manifest {
    file: String,
    folder: String,
    folder_expanded: String,
    root_folder: String,
    root_folder_expanded: String,
    file_names: HashMap<String, String>,
    file_extensions: HashMap<String, String>,
    folder_names: HashMap<String, (String, String)>,
}

/// The manifest with every icon name resolved to its bundled asset path.
struct Icons {
    file: &'static str,
    folder: &'static str,
    folder_expanded: &'static str,
    root_folder: &'static str,
    root_folder_expanded: &'static str,
    file_names: HashMap<String, &'static str>,
    file_extensions: HashMap<String, &'static str>,
    folder_names: HashMap<String, (&'static str, &'static str)>,
}

fn icons() -> &'static Icons {
    static ICONS: OnceLock<Icons> = OnceLock::new();
    ICONS.get_or_init(|| {
        let manifest: Manifest = serde_json::from_str(MANIFEST).unwrap_or_else(|err| {
            log::error!("Invalid Material icon manifest: {err:#}");
            Manifest::default()
        });
        // Bundled assets need `&'static str` paths. There is one per icon
        // (about 1,300), created once and shared by every lookup.
        let mut paths: HashMap<String, &'static str> = HashMap::new();
        let mut path = |name: &str| -> &'static str {
            if let Some(path) = paths.get(name) {
                return path;
            }
            let leaked: &'static str =
                Box::leak(format!("bundled/svg/material/{name}.svg").into_boxed_str());
            paths.insert(name.to_owned(), leaked);
            leaked
        };
        Icons {
            file: path(&manifest.file),
            folder: path(&manifest.folder),
            folder_expanded: path(&manifest.folder_expanded),
            root_folder: path(&manifest.root_folder),
            root_folder_expanded: path(&manifest.root_folder_expanded),
            file_names: manifest
                .file_names
                .iter()
                .map(|(name, icon)| (name.clone(), path(icon)))
                .collect(),
            file_extensions: manifest
                .file_extensions
                .iter()
                .map(|(extension, icon)| (extension.clone(), path(icon)))
                .collect(),
            folder_names: manifest
                .folder_names
                .iter()
                .map(|(name, (closed, open))| (name.clone(), (path(closed), path(open))))
                .collect(),
        }
    })
}

/// The bundled SVG for a file, given its path or name.
pub fn file_icon(path: &str) -> &'static str {
    let icons = icons();
    let name = file_name(path).to_lowercase();
    if let Some(icon) = icons.file_names.get(&name) {
        return icon;
    }
    // Longest extension first: "a.controller.ts" tries "controller.ts", then "ts".
    // A leading dot counts too, so ".env" matches the "env" extension.
    name.match_indices('.')
        .find_map(|(index, _)| icons.file_extensions.get(&name[index + 1..]).copied())
        .unwrap_or(icons.file)
}

/// The bundled SVG for a folder. Workspace roots get the root folder icon
/// unless their name has its own icon.
pub fn folder_icon(path: &str, expanded: bool, is_root: bool) -> &'static str {
    let icons = icons();
    let name = file_name(path).to_lowercase();
    match (icons.folder_names.get(&name), expanded, is_root) {
        (Some((_, open)), true, _) => open,
        (Some((closed, _)), false, _) => closed,
        (None, true, true) => icons.root_folder_expanded,
        (None, false, true) => icons.root_folder,
        (None, true, false) => icons.folder_expanded,
        (None, false, false) => icons.folder,
    }
}

fn file_name(path: &str) -> &str {
    path.trim_end_matches(['/', '\\'])
        .rsplit(['/', '\\'])
        .next()
        .unwrap_or(path)
}

